PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password TEXT NOT NULL,country TEXT DEFAULT 'India',style TEXT DEFAULT 'Balanced',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS trips(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,name TEXT NOT NULL,start_date TEXT NOT NULL,end_date TEXT NOT NULL,description TEXT,budget REAL DEFAULT 0,cover TEXT,style TEXT DEFAULT 'Balanced',is_public INTEGER DEFAULT 0,share_token TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS stops(id INTEGER PRIMARY KEY AUTOINCREMENT,trip_id INTEGER NOT NULL,city TEXT NOT NULL,start_date TEXT NOT NULL,end_date TEXT NOT NULL,FOREIGN KEY(trip_id) REFERENCES trips(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS activities(id INTEGER PRIMARY KEY AUTOINCREMENT,stop_id INTEGER NOT NULL,name TEXT NOT NULL,time TEXT,cost REAL DEFAULT 0,type TEXT DEFAULT 'Experience',description TEXT,FOREIGN KEY(stop_id) REFERENCES stops(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS discover(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,country TEXT,description TEXT,image TEXT,cost_index TEXT,type TEXT,default_cost REAL DEFAULT 0,popular INTEGER DEFAULT 0);
